mapper.update:
update weather_analyse
set is_deleted = 1
where tenant_id = #{tenantId}
  and industry_code = #{industryCode}
  and app_ver_code = #{appVerCode}

mapper.select:
SELECT
IFNULL(AVG(temperature), 0) AS temperatureMonth,
IFNULL(AVG(precipitation), 0) AS precipitationMonth
FROM
weather_analyse

    and is_deleted = 0

        and industry_code = #{industryCode}


        and tenant_id = #{tenantId}


        and app_ver_code = #{appVerCode}


        AND create_time BETWEEN #{startTime} AND #{endTime}

select id,
       tenant_id
from weather_analyse
where is_deleted = 0
  and tenant_id = #{param.tenantId}
  and industry_code = #{param.industryCode}
  and app_ver_code = #{param.appVerCode}
  and create_time between #{startTime} and #{endTime} limit 1

SELECT DATE_FORMAT(MIN(create_time), '%Y') AS years, DATE_FORMAT(MIN(create_time), '%m') AS times, DATE_FORMAT(MIN(create_time), '%d') AS days,
DATE_FORMAT(MIN(create_time), '%Y-%m-%d') AS dayDateTime, IFNULL(AVG(temperature), 0) AS temperature, IFNULL(AVG(precipitation), 0) AS precipitation FROM weather_analyse
and is_deleted = 0
and industry_code = #{param.industryCode}
and tenant_id = #{param.tenantId}
and app_ver_code = #{param.appVerCode}
AND create_time BETWEEN #{param.startTime} AND #{param.endTime}
GROUP BY
DATE_FORMAT(create_time, '%Y年%m月%d日')
DATE_FORMAT(create_time, '%Y年%m月%d日')
DATE_FORMAT(create_time, '%Y年%m月')
order by DATE_FORMAT(create_time, '%Y年%m月%d日') asc
